import os
from typing import Dict, Any, Optional
import boto3
from botocore.exceptions import ClientError

def extract_expense_fields(image_path: str) -> Dict[str, Any]:
    """
    Extract expense fields from an image using Amazon Textract AnalyzeExpense.
    Returns normalized JSON with standard expense fields.
    """
    client = boto3.client(
        'textract',
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY'),
        region_name=os.environ.get('AWS_REGION', 'us-east-1')
    )

    with open(image_path, 'rb') as image_file:
        image_bytes = image_file.read()

    try:
        response = client.analyze_expense(Document={'Bytes': image_bytes})
    except ClientError as e:
        raise RuntimeError(f"Textract API error: {e}")

    normalized = {
        "vendor_name": None,
        "invoice_date": None,
        "invoice_number": None,
        "total_amount": None,
        "tax_amount": None,
        "currency": "USD",
        "line_items": []
    }

    if 'ExpenseDocuments' not in response or not response['ExpenseDocuments']:
        return normalized

    expense_doc = response['ExpenseDocuments'][0]

    for summary_field in expense_doc.get('SummaryFields', []):
        field_type = summary_field.get('Type', {}).get('Text', '').lower()
        value_text = summary_field.get('ValueDetection', {}).get('Text')

        if not value_text:
            continue

        if 'vendor' in field_type or 'seller' in field_type:
            normalized["vendor_name"] = value_text
        elif 'date' in field_type:
            normalized["invoice_date"] = value_text
        elif 'invoice' in field_type and 'number' in field_type:
            normalized["invoice_number"] = value_text
        elif 'total' in field_type:
            normalized["total_amount"] = float(value_text.replace('$', '').replace(',', ''))
        elif 'tax' in field_type:
            normalized["tax_amount"] = float(value_text.replace('$', '').replace(',', ''))
        elif 'currency' in field_type:
            normalized["currency"] = value_text

    for line_item_group in expense_doc.get('LineItemGroups', []):
        for line_item in line_item_group.get('LineItems', []):
            line_item_data = {}
            for field in line_item.get('LineItemExpenseFields', []):
                field_type = field.get('Type', {}).get('Text', '').lower()
                value_text = field.get('ValueDetection', {}).get('Text')
                if value_text:
                    if 'item' in field_type or 'description' in field_type:
                        line_item_data["description"] = value_text
                    elif 'amount' in field_type or 'price' in field_type:
                        try:
                            line_item_data["amount"] = float(value_text.replace('$', '').replace(',', ''))
                        except ValueError:
                            line_item_data["amount"] = None
                    elif 'quantity' in field_type:
                        try:
                            line_item_data["quantity"] = float(value_text)
                        except ValueError:
                            line_item_data["quantity"] = None

            if line_item_data:
                normalized["line_items"].append(line_item_data)

    return normalized
